<script setup lang="ts">
import {ref,computed,watch} from 'vue';import {useDispatchStore} from './stores/dispatch';import {rehearsalTitles,rehearsalNext} from './traffic-rehearsal';
const store=useDispatchStore(),checks=ref([false,false,false,false]);const phase=computed(()=>store.rehearsalPhase);watch(phase,()=>checks.value=[false,false,false,false]);
const messages=['选择联动任务DEMO-TASK-002：查看SHARED-01红色区域、阻塞车AGV-01；选择001查看持有资源和原路线。','只记录取消意图，冻结后续步骤；原车和路权仍保留。','3003接受不是动作结束。不得立刻释放资源或重复派发运输。','1110确认原运输结束，只进入CancellationReview；过期租约也不能自动放行。','逐项核对车辆停车与位置、箱体归属、PLC原周期和路权。缺任一项保持冻结。','这里的资源解除是明确模拟的现场处置，不是车辆回执自动释放。实际须由后台核验。','仅关闭取消，不补记九步已完成；恢复批次仍需核对全场条目。','模拟全场核对放行，不启动通信、不发送新运输。实际Web操作仍受原后台门禁。'];
function next(){if(phase.value!==null)store.setRehearsal(rehearsalNext(phase.value,checks.value));}
</script><template><section class="traffic-rehearsal"><h2>取消等待与恢复 · 浏览器合成演练</h2><p>全部状态与确认均为合成教学，不调用取消、恢复、PLC或AGV控制接口，不作为协议测试或现场证据。</p><button @click="store.setRehearsal(0)">开始 / 重置演练</button><template v-if="phase!==null"><b>{{phase+1}} / 8 · {{rehearsalTitles[phase]}}</b><p>{{messages[phase]}}</p><div v-if="phase===4"><label v-for="(name,i) in ['车辆停车及位置','载荷箱体与原任务归属','原PLC握手周期','原路权处置依据']" :key="i"><input v-model="checks[i]" type="checkbox"/>模拟已核对：{{name}}</label></div><button :disabled="phase===7||(phase===4&&!checks.every(Boolean))" @click="next">{{phase===4?'模拟核对并处置占用':phase===5?'模拟关闭取消':phase===6?'模拟全场核对放行':'下一阶段（模拟）'}}</button></template></section></template>
<style scoped>.traffic-rehearsal{border:1px solid #ad873c;background:#27251f;padding:14px;margin-bottom:16px;font-size:12px;line-height:1.9}.traffic-rehearsal h2{font-size:15px;color:#ffd787}.traffic-rehearsal button{margin:6px 16px 6px 0}.traffic-rehearsal label{display:inline-flex;margin:6px 12px 6px 0;gap:5px}</style>
